pub fn predict(x:&[f32;25])->f64 {let mut y=BIAS;for tree in TREES {let mut k=0;while tree[k].0<25 {let n=tree[k];k=if (x[n.0] as f64)<n.1 {n.2}else{n.3};}y+=tree[k].4;}y}
